selector_to_html = {"a[href=\"main/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.main<a class=\"headerlink\" href=\"#module-dataflow.registry.main\" title=\"Link to this heading\">\u00b6</a></h1><h2>Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"utils/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.utils<a class=\"headerlink\" href=\"#module-dataflow.registry.utils\" title=\"Link to this heading\">\u00b6</a></h1><p>Utilities for the Haive Registry System.</p><p>This package provides utility functions and helpers for the registry\nsystem, including logging utilities and other common functionality.</p>", "a[href=\"importers/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.importers<a class=\"headerlink\" href=\"#module-dataflow.registry.importers\" title=\"Link to this heading\">\u00b6</a></h1><p>Importers for the Haive Registry System.</p><p>This package provides importers for external data sources, allowing the\nregistry to import models, providers, and other components from external\nsystems.</p>", "a[href=\"serialization/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.serialization<a class=\"headerlink\" href=\"#module-dataflow.registry.serialization\" title=\"Link to this heading\">\u00b6</a></h1><p>Serialization utilities for the Haive Registry System.</p><p>This module provides tools for serializing and deserializing complex Python objects\nfor storage in the registry database. It handles the conversion of objects that\naren\u2019t natively JSON-serializable, such as classes, functions, and custom types.</p>", "a[href=\"#module-dataflow.registry\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry<a class=\"headerlink\" href=\"#module-dataflow.registry\" title=\"Link to this heading\">\u00b6</a></h1><p>Haive Registry System.</p><p>This package provides a comprehensive registry system for Haive components,\nenabling discovery, registration, and management of various components like\nagents, tools, engines, and games.</p>", "a[href=\"db/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.db<a class=\"headerlink\" href=\"#module-dataflow.registry.db\" title=\"Link to this heading\">\u00b6</a></h1><p>Database schema and operations for the registry system.</p><p>This module provides database integration for the registry system, focusing on:\n1. Schema creation and migration\n2. Supabase integration\n3. Relations between registry items and state schemas\n4. Agent graph storage</p>", "a[href=\"core/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.core<a class=\"headerlink\" href=\"#module-dataflow.registry.core\" title=\"Link to this heading\">\u00b6</a></h1><p>Core Registry System for Haive.</p><p>This module implements the central registry system for the Haive framework,\nproviding functionality for registering, querying, and managing various components\nsuch as agents, tools, engines, and other entity types.</p>", "a[href=\"#submodules\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Submodules<a class=\"headerlink\" href=\"#submodules\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"lazy_core/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.lazy_core<a class=\"headerlink\" href=\"#module-dataflow.registry.lazy_core\" title=\"Link to this heading\">\u00b6</a></h1><p>Lazy-loading Registry System for Haive.</p><p>This module provides a lazy-loading version of the registry system that\nonly initializes the Supabase connection when actually needed,\npreventing heavy initialization at import time.</p>", "a[href=\"base/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.base<a class=\"headerlink\" href=\"#module-dataflow.registry.base\" title=\"Link to this heading\">\u00b6</a></h1><p>Base registry system for Haive components.</p><p>This module provides the fundamental registry system that all specific\nregistries inherit from. It handles registration, discovery, database\npersistence, and retrieval of components.</p>", "a[href=\"registries/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.registries<a class=\"headerlink\" href=\"#module-dataflow.registry.registries\" title=\"Link to this heading\">\u00b6</a></h1><p>Registries - TODO: Add brief description.</p><p>TODO: Add detailed description of module functionality</p>", "a[href=\"models/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.models<a class=\"headerlink\" href=\"#module-dataflow.registry.models\" title=\"Link to this heading\">\u00b6</a></h1><p>Models for the Haive Registry System.</p><p>This module defines the core data models used by the registry system to represent\ndifferent types of entities, configurations, dependencies, and other components.\nThese models provide a structured way to store and retrieve information about\nvarious components in the Haive ecosystem.</p>", "a[href=\"providers/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.providers<a class=\"headerlink\" href=\"#module-dataflow.registry.providers\" title=\"Link to this heading\">\u00b6</a></h1><p>Providers - TODO: Add brief description.</p><p>TODO: Add detailed description of module functionality</p>", "a[href=\"discovery/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.discovery<a class=\"headerlink\" href=\"#module-dataflow.registry.discovery\" title=\"Link to this heading\">\u00b6</a></h1><p>Discovery mechanisms for the Haive Registry System.</p><p>This module provides functionality for automatically discovering and registering\nvarious components in the Haive ecosystem, such as agents, tools, engines, and games.\nIt implements introspection mechanisms to find components based on naming conventions,\nclass inheritance, and module structure.</p>", "a[href=\"bin/index.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">dataflow.registry.bin<a class=\"headerlink\" href=\"#module-dataflow.registry.bin\" title=\"Link to this heading\">\u00b6</a></h1><p>Bin module.</p><p>This module is part of the Haive framework.\nLocation: haive-dataflow/src/haive/dataflow/registry/bin</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }
            link.classList.add('has-tooltip');
            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: true, theme: 'light-border', delay: [200, 100], duration: [200, 100],
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
